from concurrent.futures import ThreadPoolExecutor
from datetime import datetime,timezone
from pathlib import Path
import json,shlex,subprocess,urllib.request
run=Path(__file__).resolve().parent
controller=json.loads((run/'controller-current.json').read_text())
cluster=json.loads((run/'cluster-current.json').read_text())
rows=[]
for entry in cluster:
 if not entry['ssh'].get('data'):continue
 node=entry['node'];remote=entry['ssh']['data']
 interfaces=json.loads(remote['network_addresses']['stdout'])
 for i in interfaces:
  if i['ifname']=='eth0':
   for a in i.get('addr_info',[]):
    if a.get('family')=='inet':rows.append({'node':node,'observed_lan_ip':a['local']})
opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
for row in rows:
 url='http://'+row['observed_lan_ip']+':5000/health'
 try:
  with opener.open(url,timeout=3) as response:
   data=json.loads(response.read(65536))
   row['lan_health']={'url':url,'status':response.status,'node':data.get('node'),'identity_matches':data.get('node')==row['node']}
 except (OSError,ValueError) as e:row['lan_health']={'url':url,'error':str(e)}
 row['controller_route']=subprocess.run(['ip','-j','route','get',row['observed_lan_ip']],capture_output=True,text=True,timeout=3).stdout
p=subprocess.run(['tailscale','status','--json'],capture_output=True,text=True,timeout=5)
mesh={'returncode':p.returncode,'stderr':p.stderr[:1000],'peers':[]}
if p.returncode==0:
 data=json.loads(p.stdout)
 for peer in data.get('Peer',{}).values():
  if peer.get('HostName') in ('pi01','pi02','pi03'):
   mesh['peers'].append({k:peer.get(k) for k in ('HostName','DNSName','TailscaleIPs','Online','Active','LastSeen','OS')})
report={'observed_at_utc':datetime.now(timezone.utc).isoformat(),'lan_checks':rows,'tailscale_status':mesh}
(run/'network-followup.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report,indent=2))
